{
  "interpretation": {
    "name": "TightenVariantFastenersLine2AndReturnTool",
    "scope": {"line": 2, "station": "st2", "tool": "NR7", "variant": "F30"},
    "goal": "Tighten the fasteners of variant F30 at station st2 of line 2 with the shared nutrunner NR7, evaluate and record the result, then return the tool to the crib and release the reservation so other lines are not blocked.",
    "constraints": [
      "NR7 must be reserved before any use and released after it is returned",
      "NR7 must be at station st2 before configure-tool and tighten-fasteners",
      "The tightening program must come only from get-program for variant F30, with no literal values in the Recipe",
      "The tightening must be evaluated and recorded for traceability",
      "transport-tool must be delegated to the executor agvexecutor",
      "The tool must be returned to the crib and the reservation released at the end"
    ],
    "preference": "Release the shared tool as soon as it is no longer needed",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line2-f30-tighten-and-return-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve-nr7",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "get-f30-program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-nr7-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {
            "name": "configure-nr7",
            "service": "configure-tool",
            "next": ["tighten-nr7"],
            "dep": ["get-f30-program", "reserve-nr7"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-nr7",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure-nr7", "reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {
            "name": "evaluate-nr7-tightening",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-nr7", "get-f30-program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record-nr7-tightening",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {
            "name": "transport-nr7-to-crib",
            "service": "transport-tool",
            "next": ["release-nr7"],
            "dep": ["reserve-nr7"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          },
          {
            "name": "release-nr7",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve-nr7"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
